begin;
create temporary table qa_staff_ctx on commit drop as select (select user_id from public.training_admins order by created_at limit 1) actor,gen_random_uuid() other,gen_random_uuid() outsider,gen_random_uuid() stage_a,gen_random_uuid() stage_b,gen_random_uuid() staff_a,gen_random_uuid() staff_b;
grant select on qa_staff_ctx to authenticated,anon;
insert into auth.users(id,email,role,aud) select other,'qa-staff-'||other::text||'@example.invalid','authenticated','authenticated' from qa_staff_ctx union all select outsider,'qa-outsider-'||outsider::text||'@example.invalid','authenticated','authenticated' from qa_staff_ctx;
insert into public.training_admins(user_id) select other from qa_staff_ctx;
insert into public.training_stages(id,title,place,start,"end",owner_id) select stage_a,'QA staff A','test',date '2026-12-05',date '2026-12-06',actor from qa_staff_ctx union all select stage_b,'QA staff B','test',date '2026-12-05',date '2026-12-06',other from qa_staff_ctx;
insert into public.training_staff(id,stage_id,first_name,last_name,workshop) select staff_a,stage_a,'اختبار','أ','ورشة أ' from qa_staff_ctx union all select staff_b,stage_b,'اختبار','ب','ورشة ب' from qa_staff_ctx;
insert into storage.objects(bucket_id,name) select 'training-staff-photos',staff_a::text||'/portrait' from qa_staff_ctx union all select 'training-staff-photos',staff_b::text||'/portrait' from qa_staff_ctx;
set local role authenticated;
select set_config('request.jwt.claims',(select jsonb_build_object('sub',actor,'role','authenticated')::text from qa_staff_ctx),true);
do $$ declare q record;n integer;blocked boolean;begin
 select * into q from qa_staff_ctx;
 if (select count(*) from public.training_staff where id=q.staff_a)<>1 or (select count(*) from public.training_staff where id=q.staff_b)<>0 then raise exception 'Staff scope failed';end if;
 if (select count(*) from storage.objects where bucket_id='training-staff-photos' and name=q.staff_a::text||'/portrait')<>1 or (select count(*) from storage.objects where bucket_id='training-staff-photos' and name=q.staff_b::text||'/portrait')<>0 then raise exception 'Staff photo privacy failed';end if;
 update public.training_staff set workshop='updated workshop' where id=q.staff_a;get diagnostics n=row_count;if n<>1 then raise exception 'Own update denied';end if;
 update public.training_staff set workshop='forbidden' where id=q.staff_b;get diagnostics n=row_count;if n<>0 then raise exception 'Foreign update allowed';end if;
 blocked=false;begin update public.training_staff set stage_id=q.stage_b where id=q.staff_a;exception when insufficient_privilege then blocked=true;end;if not blocked then raise exception 'Foreign reassignment allowed';end if;
 blocked=false;begin insert into public.training_staff(stage_id,first_name,last_name,workshop) values(q.stage_b,'wrong','stage','workshop');exception when insufficient_privilege then blocked=true;end;if not blocked then raise exception 'Foreign insert allowed';end if;
 insert into public.training_staff(stage_id,first_name,last_name,workshop) values(q.stage_a,'own','creation','workshop');
 insert into storage.objects(bucket_id,name) values('training-staff-photos',q.staff_a::text||'/own-upload');
 blocked=false;begin insert into storage.objects(bucket_id,name) values('training-staff-photos',q.staff_b::text||'/forbidden-upload');exception when insufficient_privilege then blocked=true;end;if not blocked then raise exception 'Foreign photo upload allowed';end if;
 blocked=false;begin update public.training_staff set photo_key=q.staff_b::text||'/portrait',photo_type='image/png' where id=q.staff_a;exception when check_violation then blocked=true;end;if not blocked then raise exception 'Foreign photo reference allowed';end if;
 update public.training_staff set photo_key=q.staff_a::text||'/portrait',photo_type='image/png',deleted_at=now() where id=q.staff_a;
 if exists(select 1 from storage.objects where bucket_id='training-staff-photos' and name=q.staff_a::text||'/portrait') then raise exception 'Deleted staff photo exposed';end if;
 update public.training_staff set deleted_at=null where id=q.staff_a;
 if (select count(*) from storage.objects where bucket_id='training-staff-photos' and name=q.staff_a::text||'/portrait')<>1 then raise exception 'Photo not restored';end if;
end $$;
select set_config('request.jwt.claims',(select jsonb_build_object('sub',other,'role','authenticated')::text from qa_staff_ctx),true);
do $$ declare q record;n integer;begin select * into q from qa_staff_ctx;
 if (select count(*) from public.training_staff where id=q.staff_b)<>1 or (select count(*) from public.training_staff where id=q.staff_a)<>0 then raise exception 'Reverse scope failed';end if;
 update public.training_staff set deleted_at=now() where id=q.staff_a;get diagnostics n=row_count;if n<>0 then raise exception 'Foreign deletion allowed';end if;
end $$;
select set_config('request.jwt.claims',(select jsonb_build_object('sub',outsider,'role','authenticated')::text from qa_staff_ctx),true);
do $$ declare q record;blocked boolean:=false;begin select * into q from qa_staff_ctx;
 if exists(select 1 from public.training_staff where id in(q.staff_a,q.staff_b)) or exists(select 1 from storage.objects where bucket_id='training-staff-photos' and name in(q.staff_a::text||'/portrait',q.staff_b::text||'/portrait')) then raise exception 'Unapproved account access';end if;
 begin insert into public.training_staff(stage_id,first_name,last_name,workshop) values(q.stage_a,'unapproved','account','workshop');exception when insufficient_privilege then blocked=true;end;if not blocked then raise exception 'Unapproved write allowed';end if;
end $$;
reset role;
set local role anon;
do $$ declare blocked boolean:=false;begin begin perform count(*) from public.training_staff;exception when insufficient_privilege then blocked=true;end;if not blocked then raise exception 'Anonymous table access allowed';end if;end $$;
reset role;
rollback;
select 'PASS: staff CRUD, both owner scopes, approved accounts, private photo reads/uploads, forbidden reassignment, soft deletion/restoration, anonymous denial' as test_result;
